import{_ as t,o as i,c as r,a3 as n}from"./chunks/framework.z_KJ15Ep.js";const f=JSON.parse('{"title":"Die Schulstatistik vorbereiten und prüfen","description":"","frontmatter":{},"headers":[],"relativePath":"schild3/statistik.md","filePath":"schild3/statistik.md"}'),a={name:"schild3/statistik.md"};function s(l,e,h,o,u,d){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="die-schulstatistik-vorbereiten-und-prufen" tabindex="-1">Die Schulstatistik vorbereiten und prüfen <a class="header-anchor" href="#die-schulstatistik-vorbereiten-und-prufen" aria-label="Permalink to &quot;Die Schulstatistik vorbereiten und prüfen&quot;">​</a></h1><p>Bereiten Sie die gespeicherten Daten vor, prüfen Sie Fehler und erstellen Sie anschließend die Dateien für die amtliche Schulstatistik. Der Ablauf beschreibt die Übergabe aus SchILD-NRW an ASDPC.</p><h2 id="daten-vorbereiten-und-prufen" tabindex="-1">Daten vorbereiten und prüfen <a class="header-anchor" href="#daten-vorbereiten-und-prufen" aria-label="Permalink to &quot;Daten vorbereiten und prüfen&quot;">​</a></h2><ol><li><a href="/schild3/import-export-statistik/vorbereitende-massnahmen-zur-statistik-in-schild-nrw-tutorial.html">Die amtliche Schulstatistik vorbereiten</a> mit den Hinweisen für unterschiedliche Schulformen.</li><li>Die <a href="/schild3/import-export-statistik/statistik-fuer-it-nrw-verwaltung.html">Statistikfunktionen</a> aufrufen und <a href="/zeugnisse/vorbereitung/gesamtpruefung-der-daten-verwaltung-statistik-fuer-it-nrw.html">die Gesamtprüfung durchführen</a>.</li><li>Das <a href="/schild3/import-export-statistik/fehlerprotokoll-anzeigen-verwaltung-statistik-fuer-it-nrw.html">Fehlerprotokoll</a> abarbeiten und Korrekturen möglichst in SchILD-NRW vornehmen.</li><li>Nach der Prüfung <a href="/schild3/import-export-statistik/daten-exportieren-verwaltung-statistik-fuer-it-nrw.html">die benötigten Statistikdateien exportieren</a>.</li></ol><h2 id="technische-fehler-beheben" tabindex="-1">Technische Fehler beheben <a class="header-anchor" href="#technische-fehler-beheben" aria-label="Permalink to &quot;Technische Fehler beheben&quot;">​</a></h2><ul><li>Fehlende Bibliotheken: <a href="/hilfe/probleme/hilfe-bei-problemen-verwaltung-statistik-fuer-it-nrw.html">Statistikdateien unter Windows registrieren</a>.</li><li>Darstellung, parallele Installation und Abgabe: <a href="/hilfe/probleme/fehleranalyse-zur-statistik-tutorial.html">Fehler bei der Statistikvorbereitung und Abgabe beheben</a>.</li></ul><p>Die Gesamtprüfung in SchILD-NRW ersetzt nicht alle Prüfungen des Statistikprogramms. Die Hinweise und Schlüsselverzeichnisse der jeweiligen Erhebung finden Sie über die im Artikel verlinkten Angebote von IT.NRW.</p>',7)])])}const b=t(a,[["render",s]]);export{f as __pageData,b as default};
